import React from 'react';
import { motion } from 'framer-motion';

const Hero = () => {
  return (
    <section className="relative min-h-screen flex items-center px-10 bg-gradient-to-br from-gray-900 via-indigo-900 to-black text-white overflow-hidden">

      {/* Glow background */}
      <div className="absolute w-[500px] h-[500px] bg-fuchsia-500 rounded-full blur-3xl opacity-30 top-[-100px] left-[-100px]"></div>
      <div className="absolute w-[400px] h-[400px] bg-cyan-500 rounded-full blur-3xl opacity-20 bottom-[-100px] right-[-100px]"></div>

      <div className="grid md:grid-cols-2 gap-10 items-center w-full max-w-7xl mx-auto">

        {/* LEFT */}
        <motion.div
          initial={{ opacity: 0, x: -50 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.8 }}
        >
          <h1 className="text-5xl font-extrabold leading-tight mb-6">
            Smart Healthcare <br />
            <span className="text-fuchsia-400">For Smart Students</span>
          </h1>

          <p className="text-gray-300 mb-8 text-lg">
            Skip queues. Book instantly. Manage your health digitally.
          </p>

          <div className="flex gap-4">
            <button className="bg-yellow-400 text-black px-6 py-3 rounded-xl font-bold hover:scale-110 transition">
              Book Appointment
            </button>
            <button className="bg-gradient-to-r from-indigo-500 to-fuchsia-500 px-6 py-3 rounded-xl font-bold hover:scale-110 transition">
              Live Queue
            </button>
          </div>
        </motion.div>

        {/* RIGHT */}
        <motion.div
          initial={{ opacity: 0, x: 50 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.8 }}
          className="hidden md:block"
        >
          <div className="bg-white/10 backdrop-blur-lg p-8 rounded-3xl shadow-2xl border border-white/20">
            <p className="text-sm text-gray-300 mb-2">Live Queue</p>
            <h2 className="text-2xl font-bold mb-4">Now Serving</h2>
            <div className="text-4xl font-bold text-green-400">A102</div>
            <p className="mt-2 text-gray-400">Estimated wait: 5 mins</p>
          </div>
        </motion.div>

      </div>
    </section>
  );
};

export default Hero;
